    26	
    27	    private static final Logger logger = LoggerFactory.getLogger(CompensationServiceImpl.class);
    28	    private String dbPassword = "Admin@123";
    29	    private static final String DB_URL = "jdbc:mysql://10.0.1.50:3306/compensation_db";
    30	    private static final String DB_USER = "app_user";
    31	    private static final String BASE_EXPORT_DIR = "/opt/compensation-service/exports/";
    32	
    33	    @Autowired
    34	    private CompensationDAO compensationDAO;
    35	
    36	    private Object lockObject = new Object();
