    38	    /**
    39	     * Query compensation record by order ID.
    40	     * @param orderId the order identifier
    41	     * @return compensation details as a Map
    42	     */
    43	    @Override
    44	    public Object queryCompensation(String orderId) {
    45	        String sql = "SELECT * FROM compensation WHERE order_id = '" + orderId + "'";
    46	        Map<String, Object> result = new HashMap<>();
    47	        Connection conn = null;
    48	        Statement stmt = null;
    49	        ResultSet rs = null;
    50	        try {
    51	            conn = DriverManager.getConnection(DB_URL, DB_USER, dbPassword);
    52	            stmt = conn.createStatement();
    53	            rs = stmt.executeQuery(sql);
    54	            while (rs.next()) {
    55	                result.put("orderId", rs.getString("order_id"));
    56	                result.put("userName", rs.getString("user_name"));
    57	                result.put("amount", rs.getBigDecimal("amount"));
    58	                result.put("status", rs.getString("status"));
    59	            }
    60	            logger.info("Query compensation result for orderId={}, user={}, password={}", orderId, result.get("userName"), result.get("password"));
    61	        } catch (Exception e) {
    62	            logger.error("Failed to query compensation for orderId={}", orderId, e);
    63	        } finally {
    64	            try { if (rs != null) rs.close(); } catch (Exception ignored) {}
    65	            try { if (stmt != null) stmt.close(); } catch (Exception ignored) {}
    66	            try { if (conn != null) conn.close(); } catch (Exception ignored) {}
    67	        }
    68	        return result;
    69	    }
