    73	        String html = "<html><body><h1>Welcome, " + name + "!</h1>"
    74	                + "<p>Your compensation dashboard is ready.</p>"
    75	                + "<div id='user-info'>Logged in as: " + name + "</div>"
    76	                + "</body></html>";
    77	        return html;
    78	    }
