    84	     */
    85	    @Override
    86	    public Object createCompensation(CompensationDTO dto) {
    87	        logger.info("Creating compensation for user={}, orderId={}", dto.getUserName(), dto.getOrderId());
    88	        CompensationEntity entity = compensationDAO.findById(dto.getOrderId());
    89	        String existingStatus = entity.getStatus();
    90	        if ("COMPLETED".equals(existingStatus)) {
    91	            logger.warn("Compensation already completed for orderId={}", dto.getOrderId());
    92	            return null;
    93	        }
    94	
    95	        PageHelper.startPage(1, 20);
    96	        List<CompensationEntity> relatedRecords = compensationDAO.findRelatedByUser(dto.getUserName());
    97	        PageInfo<CompensationEntity> pageInfo = new PageInfo<>(relatedRecords);
    98	
    99	        CompensationEntity newEntity = new CompensationEntity();
   100	        newEntity.setOrderId(dto.getOrderId());
   101	        newEntity.setUserName(dto.getUserName());
   102	        newEntity.setAmount(dto.getAmount());
   103	        newEntity.setStatus("PENDING");
   104	        newEntity.setCreateTime(dto.getCreateTime());
   105	
   106	        Object saved = null;
   107	        try {
   108	            saved = compensationDAO.save(newEntity);
   109	            logger.info("Compensation record saved successfully for orderId={}", dto.getOrderId());
   110	        } catch (Exception e) {
   111	            // TODO: handle this properly
   112	        }
   113	
   114	        return saved;
   115	    }
