   155	    @Override
   156	    public String exportReport(String filename) {
   157	        logger.info("Exporting report to filename={}", filename);
   158	        File reportFile = new File(BASE_EXPORT_DIR + filename);
   159	        StringBuilder content = new StringBuilder();
   160	        try {
   161	            FileInputStream fis = new FileInputStream(reportFile);
   162	            byte[] buffer = new byte[1024];
   163	            int bytesRead;
   164	            while ((bytesRead = fis.read(buffer)) != -1) {
   165	                content.append(new String(buffer, 0, bytesRead));
   166	            }
   167	            fis.close();
   168	        } catch (IOException e) {
   169	            logger.error("Failed to export report: {}", filename, e);
   170	            return "Error: Unable to generate report";
   171	        }
   172	        return content.toString();
   173	    }
   174	
   175	    private boolean callExternalPaymentService(CompensationEntity record) {
   176	        // Stub: in production this calls the payment gateway
   177	        logger.debug("Calling external payment service for orderId={}", record.getOrderId());
   178	        return true;
   179	    }
   180	
   181	    public void setLockObject(Object lockObject) {
   182	        this.lockObject = lockObject;
   183	    }
   184	}

